import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a number theory contest, you are given an odd integer {m} ≥ 3 and target counts {r_count} and {b_count} with r_count > b_count ≥ 1. You may choose a positive integer x, coprime to {m}, and a consecutive interval [a+1, ..., a+b]. Let A_x be the set of integers y with y^2 ≡ 1 (mod x). Define red points as those y ∈ A_x with y ≡ −1 (mod {m}) and blue points as those y ∈ A_x with y ≡ 1 (mod {m}). You must also enforce that the exact power of 2 dividing x is 2^{two_exp} (that is, 2^{two_exp} | x and 2^{two_exp+1} ∤ x), and that the odd part of x is squarefree. Determine the minimum number N_min of distinct prime factors of x (counting 2 once) that guarantees one can construct such an x and interval [a+1, ..., a+b] with exactly {r_count} red and exactly {b_count} blue points.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Randomly generate parameters ensuring non-trivial instances
# m: odd >= 3
# r_count: reasonably large to make prime-factor count non-trivial
# b_count: strictly less than r_count
# two_exp: exponent of 2 in x (>=1)
for _ in range(1000):
    # Choose m as a random odd in [3, 199]
    m = rng.randrange(3, 200)
    if m % 2 == 0:
        m += 1
    if m < 3:
        m = 3
    # two_exp from {1,2,3,4}
    two_exp = rng.choice([1, 2, 3, 4])
    # r_count large: between 10^6 and 10^9 inclusive
    r_low = 10**6
    r_high = 10**9
    r_count = rng.randint(r_low, r_high)
    # b_count between 1 and r_count-1, not too close to r_count to avoid triviality
    b_min = 1
    b_max = r_count - 1
    if b_max <= b_min:
        continue
    # Pick b_count biased to be not extremely small or extremely close to r_count
    # Use a fraction of r_count
    frac = rng.uniform(0.2, 0.8)
    b_candidate = int(frac * r_count)
    if b_candidate <= 0 or b_candidate >= r_count:
        # fallback
        b_candidate = rng.randint(b_min, b_max)
    b_count = b_candidate
    # Compute delta from two_exp: delta=0 if two_exp==1 else 1
    delta = 0 if two_exp == 1 else 1
    # Compute ceil_log2(r_count)
    def ceil_log2(n):
        if n <= 0:
            return None
        if n == 1:
            return 0
        return (n - 1).bit_length()
    cl2 = ceil_log2(r_count)
    if cl2 is None:
        continue
    # N_min = 1 + max(0, ceil_log2(R) - delta)
    n_min = 1 + max(0, cl2 - delta)
    # Enforce difficulty: need at least 3 distinct primes required
    if n_min < 3:
        # retry
        continue
    return {
        'm': m,
        'r_count': r_count,
        'b_count': b_count,
        'two_exp': two_exp
    }
# Fallback deterministic hard instance if random fails
return {
    'm': 105,           # odd composite
    'r_count': 10**7,   # large
    'b_count': 7 * 10**6,
    'two_exp': 2        # ensures delta=1
}

    def verifier(assign):
# Validate and compute the minimum number of distinct prime factors N_min.
# Return (True, answer) when valid; otherwise (False, None).
# The formula used is N_min = 1 + max(0, ceil_log2(r_count) - delta),
# where delta = 0 if two_exp==1, else 1.
try:
    m = int(assign.get('m', None))
    r_count = int(assign.get('r_count', None))
    b_count = int(assign.get('b_count', None))
    two_exp = int(assign.get('two_exp', None))
except Exception:
    # malformed
    return (False, None)
# Basic validation
if m is None or r_count is None or b_count is None or two_exp is None:
    # missing fields
    return (False, None)
if m < 3 or m % 2 == 0:
    # m must be odd >= 3
    return (False, None)
if two_exp < 1:
    # two_exp must be >=1
    return (False, None)
if not (isinstance(r_count, int) and isinstance(b_count, int)):
    return (False, None)
if r_count <= b_count or b_count < 1:
    # Target counts must satisfy r_count > b_count >= 1
    return (False, None)
# Helper: ceil_log2
def ceil_log2(n):
    if n <= 0:
        return None
    if n == 1:
        return 0
    return (n - 1).bit_length()
cl2 = ceil_log2(r_count)
if cl2 is None:
    return (False, None)
delta = 0 if two_exp == 1 else 1
n_min = 1 + max(0, cl2 - delta)
# Enforce non-triviality: at least 3 distinct primes required
if n_min < 3:
    return (False, None)
# All good
answer = n_min
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

